// Meet in the middle: does any subset of arr sum to exactly target?
function subsetSumExists(arr, target) {
  const n = arr.length;
  const half = Math.floor(n / 2);

  function allSubsetSums(part) {
    const sums = [0];
    for (const x of part) {
      const len = sums.length;
      for (let i = 0; i < len; i++) sums.push(sums[i] + x);
    }
    return sums;
  }

  const leftSums = allSubsetSums(arr.slice(0, half));
  const rightSums = allSubsetSums(arr.slice(half)).sort((a, b) => a - b);

  for (const l of leftSums) {
    // binary search for (target - l) in rightSums
    let lo = 0, hi = rightSums.length - 1;
    const need = target - l;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (rightSums[mid] === need) return true;
      if (rightSums[mid] < need) lo = mid + 1; else hi = mid - 1;
    }
  }
  return false;
}

// Reservoir sampling: pick one uniformly random node from a linked list of unknown length
function randomNode(head) {
  let result = null;
  let i = 0;
  let node = head;
  while (node !== null) {
    i++;
    if (Math.floor(Math.random() * i) === 0) result = node.val;  // replace w/ prob 1/i
    node = node.next;
  }
  return result;
}
